{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Earnings Prep Data",
    "url": "http://localhost:7805",
    "widgets_json": {
      "click_preview_table": {
        "name": "Click Preview Table",
        "description": "Preview rows whose symbol cell syncs the app.",
        "endpoint": "/click-preview-table",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "symbol",
                "headerName": "Symbol",
                "cellDataType": "text",
                "renderFn": "cellOnClick",
                "renderFnParams": {
                  "actionType": "groupBy",
                  "groupByParamName": "symbol"
                }
              },
              {
                "field": "revision_pct",
                "headerName": "Revision %",
                "cellDataType": "number",
                "formatterFn": "percent"
              }
            ]
          }
        }
      },
      "earnings_note": {
        "name": "Earnings Preview",
        "description": "Preview note for the earnings call.",
        "endpoint": "/earnings-preview",
        "type": "markdown",
        "gridData": {
          "w": 12,
          "h": 8
        },
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ]
      }
    },
    "apps_json": [
      {
        "name": "Click Preview Desk",
        "description": "Clickable preview rows and notes.",
        "tabs": {
          "table": {
            "id": "table",
            "name": "Table",
            "layout": [
              {
                "i": "click_preview_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "note": {
            "id": "note",
            "name": "Note",
            "layout": [
              {
                "i": "earnings_note",
                "x": 0,
                "y": 0,
                "w": 12,
                "h": 8
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Click Preview Sync",
            "type": "param",
            "paramName": "symbol",
            "widgetIds": [
              "click_preview_table",
              "earnings_note"
            ]
          }
        ]
      }
    ]
  }
}
